import type { Dialect } from './types';

/**
 * One schema definition → DDL for Oracle (real) and SQLite (local tests).
 * Text sizes use CHAR semantics and stay under 4000 bytes (Korean = 3 bytes/char in AL32UTF8).
 * Conventions that keep the SQL portable between the two:
 *  - every table is prefixed HR_ and avoids Oracle reserved words (DATE, LEVEL, SIZE, USER …)
 *  - calendar dates are VARCHAR2(10) 'YYYY-MM-DD' (string comparison = date comparison)
 *  - instants are TIMESTAMP (Oracle) / ISO text (SQLite)
 *  - booleans are NUMBER(1) 0/1
 *  - ids are strings generated by the app
 *  - Oracle treats '' as NULL, so optional text columns are nullable
 */

type Col = [name: string, type: string, extra?: string];
interface Table { name: string; cols: Col[]; constraints?: string[]; indexes?: string[][] }

// type helpers resolved per dialect: S(n)=string, N(p,s)=number, TS=timestamp
const T = {
  oracle: { S: (n: number) => `VARCHAR2(${n} CHAR)`, N: (p = 12, s = 0) => `NUMBER(${p},${s})`, TS: 'TIMESTAMP' },
  sqlite: { S: (_: number) => 'TEXT', N: (_p = 12, s = 0) => (s ? 'REAL' : 'INTEGER'), TS: 'TEXT' },
};

export const TABLES_IN_DROP_ORDER = [
  'HR_SESSIONS', 'HR_MESSAGES', 'HR_THREADS', 'HR_PAYSLIP_ITEMS', 'HR_PAYSLIPS', 'HR_APPROVAL_STEPS',
  'HR_LEAVES', 'HR_APPROVALS', 'HR_ATTENDANCE', 'HR_EVENTS', 'HR_NOTICES', 'HR_EMPLOYEES', 'HR_DEPTS',
];

function tables(d: Dialect): Table[] {
  const { S, N, TS } = T[d];
  return [
    { name: 'HR_DEPTS', cols: [
      ['ID', S(20), 'PRIMARY KEY'], ['NAME', S(50), 'NOT NULL'], ['COLOR', S(9), 'NOT NULL'],
      ['DESCR', S(200)], ['LEAD_ID', S(20)], ['SORT_ORDER', N(4), 'DEFAULT 0 NOT NULL'],
    ] },
    { name: 'HR_EMPLOYEES', cols: [
      ['ID', S(20), 'PRIMARY KEY'], ['LOGIN_ID', S(50), 'NOT NULL'], ['PASSWORD_HASH', S(200), 'NOT NULL'],
      ['NAME', S(50), 'NOT NULL'], ['DEPT_ID', S(20), 'NOT NULL REFERENCES HR_DEPTS(ID)'],
      ['POSITION', S(20), 'NOT NULL'], ['ROLE', S(10), "DEFAULT 'EMPLOYEE' NOT NULL"],
      ['EMAIL', S(100), 'NOT NULL'], ['PHONE', S(20)], ['JOINED_ON', S(10), 'NOT NULL'], ['LEFT_ON', S(10)],
      ['STATUS', S(10), 'NOT NULL'], ['LOCATION', S(50)], ['ANNUAL_LEAVE', N(4, 1), 'DEFAULT 15 NOT NULL'],
    ], constraints: ['CONSTRAINT UQ_HR_EMP_LOGIN UNIQUE (LOGIN_ID)'], indexes: [['IX_HR_EMP_DEPT', 'DEPT_ID']] },
    { name: 'HR_SESSIONS', cols: [
      ['TOKEN_HASH', S(64), 'PRIMARY KEY'], ['EMP_ID', S(20), 'NOT NULL REFERENCES HR_EMPLOYEES(ID)'],
      ['CREATED_AT', TS, 'NOT NULL'], ['EXPIRES_AT', TS, 'NOT NULL'],
    ] },
    { name: 'HR_ATTENDANCE', cols: [
      ['ID', S(40), 'PRIMARY KEY'], ['EMP_ID', S(20), 'NOT NULL REFERENCES HR_EMPLOYEES(ID)'],
      ['WORK_DATE', S(10), 'NOT NULL'], ['CLOCK_IN', TS, 'NOT NULL'], ['CLOCK_OUT', TS],
    ], constraints: ['CONSTRAINT UQ_HR_ATT_DAY UNIQUE (EMP_ID, WORK_DATE)'] },
    { name: 'HR_APPROVALS', cols: [
      ['ID', S(40), 'PRIMARY KEY'], ['KIND', S(10), 'NOT NULL'], ['TITLE', S(200), 'NOT NULL'],
      ['REQUESTER_ID', S(20), 'NOT NULL REFERENCES HR_EMPLOYEES(ID)'], ['BODY', S(1300)], ['AMOUNT', N(14)],
      ['STATUS', S(10), "DEFAULT '대기' NOT NULL"], ['CURRENT_SEQ', N(3), 'DEFAULT 1 NOT NULL'],
      ['CREATED_AT', TS, 'NOT NULL'],
    ], indexes: [['IX_HR_APR_REQ', 'REQUESTER_ID']] },
    { name: 'HR_APPROVAL_STEPS', cols: [
      ['APPROVAL_ID', S(40), 'NOT NULL REFERENCES HR_APPROVALS(ID)'], ['SEQ', N(3), 'NOT NULL'],
      ['APPROVER_ID', S(20), 'NOT NULL REFERENCES HR_EMPLOYEES(ID)'], ['STATUS', S(10), "DEFAULT 'WAIT' NOT NULL"],
      ['ACTED_AT', TS],
    ], constraints: ['CONSTRAINT PK_HR_APR_STEPS PRIMARY KEY (APPROVAL_ID, SEQ)'], indexes: [['IX_HR_STEP_APPROVER', 'APPROVER_ID']] },
    { name: 'HR_LEAVES', cols: [
      ['ID', S(40), 'PRIMARY KEY'], ['EMP_ID', S(20), 'NOT NULL REFERENCES HR_EMPLOYEES(ID)'],
      ['LEAVE_TYPE', S(10), 'NOT NULL'], ['FROM_DATE', S(10), 'NOT NULL'], ['TO_DATE', S(10), 'NOT NULL'],
      ['DAYS', N(4, 1), 'NOT NULL'], ['REASON', S(500)], ['STATUS', S(10), "DEFAULT '대기' NOT NULL"],
      ['APPROVAL_ID', S(40), 'REFERENCES HR_APPROVALS(ID)'], ['CREATED_AT', TS, 'NOT NULL'],
    ], indexes: [['IX_HR_LEAVE_EMP', 'EMP_ID']] },
    { name: 'HR_PAYSLIPS', cols: [
      ['ID', S(40), 'PRIMARY KEY'], ['EMP_ID', S(20), 'NOT NULL REFERENCES HR_EMPLOYEES(ID)'],
      ['PAY_MONTH', S(7), 'NOT NULL'], ['PAY_DATE', S(10), 'NOT NULL'],
    ], constraints: ['CONSTRAINT UQ_HR_PAY_MONTH UNIQUE (EMP_ID, PAY_MONTH)'] },
    { name: 'HR_PAYSLIP_ITEMS', cols: [
      ['PAYSLIP_ID', S(40), 'NOT NULL REFERENCES HR_PAYSLIPS(ID)'], ['SEQ', N(3), 'NOT NULL'],
      ['ITEM_TYPE', S(1), 'NOT NULL'], ['LABEL', S(50), 'NOT NULL'], ['AMOUNT', N(14), 'NOT NULL'],
    ], constraints: ['CONSTRAINT PK_HR_PAY_ITEMS PRIMARY KEY (PAYSLIP_ID, SEQ)', "CONSTRAINT CK_HR_PAY_ITEM_TYPE CHECK (ITEM_TYPE IN ('E','D'))"] },
    { name: 'HR_THREADS', cols: [
      ['ID', S(40), 'PRIMARY KEY'], ['EMP_A', S(20), 'NOT NULL REFERENCES HR_EMPLOYEES(ID)'], ['EMP_B', S(20), 'NOT NULL REFERENCES HR_EMPLOYEES(ID)'],
    ] },
    { name: 'HR_MESSAGES', cols: [
      ['ID', S(40), 'PRIMARY KEY'], ['THREAD_ID', S(40), 'NOT NULL REFERENCES HR_THREADS(ID)'],
      ['SENDER_ID', S(20), 'NOT NULL REFERENCES HR_EMPLOYEES(ID)'], ['BODY', S(1000), 'NOT NULL'],
      ['SENT_AT', TS, 'NOT NULL'], ['READ_AT', TS],
    ], indexes: [['IX_HR_MSG_THREAD', 'THREAD_ID']] },
    { name: 'HR_NOTICES', cols: [
      ['ID', S(40), 'PRIMARY KEY'], ['TITLE', S(200), 'NOT NULL'], ['POSTED_ON', S(10), 'NOT NULL'], ['PINNED', N(1), 'DEFAULT 0 NOT NULL'],
    ] },
    { name: 'HR_EVENTS', cols: [
      ['ID', S(40), 'PRIMARY KEY'], ['EVENT_DATE', S(10), 'NOT NULL'], ['START_TIME', S(5), 'NOT NULL'],
      ['TITLE', S(200), 'NOT NULL'], ['TAG', S(20)], ['COLOR', S(9)],
    ] },
  ];
}

/** DDL statements (no trailing semicolons — node-oracledb rejects them). */
export function ddl(d: Dialect): string[] {
  const out: string[] = [];
  for (const t of tables(d)) {
    const lines = t.cols.map(([n, ty, ex]) => `  ${n} ${ty}${ex ? ' ' + ex : ''}`);
    for (const c of t.constraints ?? []) lines.push('  ' + c);
    out.push(`CREATE TABLE ${t.name} (\n${lines.join(',\n')}\n)`);
    for (const [ix, ...cols] of t.indexes ?? []) out.push(`CREATE INDEX ${ix} ON ${t.name} (${cols.join(', ')})`);
  }
  return out;
}
